            motion_node = child
        elif child['title'].endswith(': Events'):
            events_node = child

    # Initial States (Frame 0) from Motion log
    if motion_node:
        rows = table_rows(motion_node)
        for row_idx, row in rows:
            try:
                frame = int(row['frame'])
            except (ValueError, KeyError):
                continue
            if frame == 0:
                obj_str = row.get('object', '')
                parts = obj_str.split()
                if not parts:
                    continue
                obj_id = f"Object {parts[0]}"

                fields = {}
                for col in ['x', 'y', 'vx', 'vy', 'speed']:
                    val_str = row.get(col, '')
                    try:
                        fields[col] = float(val_str)
                    except ValueError:
                        pass

                inputs_list.append({
                    "id": f"initial_{obj_id}",
                    "time": 0.0,
                    "kind": "initial_state",
                    "entities": [obj_id],
                    "fields": fields,
                    "src": [[motion_node['node_id'], row_idx, ['frame', 'object', 'x', 'y', 'vx', 'vy', 'speed']]]
                })

    # Enters / In view from Events
    if events_node:
        lines = events_node['lines']
        for line_idx, line in enumerate(lines):
            match = re.match(r"Frame (\d+): (Object \d+) \((.+?)\) (enters the scene|is in view when the video begins)", line)
            if match:
                frame = int(match.group(1))
                obj_id = match.group(2)
                kind = "enter" if "enters" in match.group(4) else "initial_presence"
                inputs_list.append({
                    "id": f"{kind}_{obj_id}_{frame}",
                    "time": float(frame),
                    "kind": kind,
                    "entities": [obj_id],
                    "fields": {},
                    "src": [[events_node['node_id'], line_idx]]
                })

    return inputs_list

