import math
import re

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model of the CLEVRER physics simulation.
    Objects slide with friction, collide, and enter/exit the scene.
    """

    end_time = recorded_end(doc, scope)

    if start is None:
        start = 0.0
    if horizon is None or horizon > (end_time if end_time else 127):
        horizon = end_time if end_time else 127

    # Get collision events from document (these are in the Events node)
    collision_events = _get_collision_events(doc, scope)

    # Get exit events from document
    exit_events = _get_exit_events(doc, scope)

    # Determine sample frames (the frames where motion is recorded)
    # Base frames: 0, 8, 16, 24, ..., up to 120, then 127
    sample_frames = set()
    for f in range(0, 128, 8):
        sample_frames.add(f)
    sample_frames.add(127)

    # Add collision frames
    for frame, objs in collision_events.items():
        sample_frames.add(frame)
        # Also add the next base frame after collision
        next_base = ((frame // 8) + 1) * 8
        if next_base <= 127:
            sample_frames.add(next_base)

    # Add exit frames
    for frame, obj in exit_events.items():
        sample_frames.add(frame)

    # Add entry frames
    entry_events_map = {}
    for inp in inputs:
        if inp['kind'] == 'enter':
            obj_id = inp['entities'][0]
            frame = int(inp['time'])
            entry_events_map[obj_id] = frame
            sample_frames.add(frame)
            # Add next frame after entry
            next_f = ((frame // 8) + 1) * 8
            if next_f <= 127:
                sample_frames.add(next_f)

    sample_frames = sorted([f for f in sample_frames if f <= horizon])

    # Initialize object states from inputs
    states = {}
    for inp in inputs:
        entities = inp['entities']

        if inp['kind'] == 'initial_state':
            obj_id = entities[0]
            fields = inp['fields']
            states[obj_id] = {
                'x': fields.get('x', 0.0),
                'y': fields.get('y', 0.0),
                'vx': fields.get('vx', 0.0),
                'vy': fields.get('vy', 0.0),
                'entered': 0.0,
                'exited': None
            }
        elif inp['kind'] == 'initial_presence':
            obj_id = entities[0]
            if obj_id not in states:
                states[obj_id] = {
                    'x': 0.0, 'y': 0.0,
                    'vx': 0.0, 'vy': 0.0,
                    'entered': 0.0,
                    'exited': None
                }
        elif inp['kind'] == 'enter':
            obj_id = entities[0]
            frame = inp['time']
            # Initialize with zero state; will be set when we reach that frame
            if obj_id not in states:
                states[obj_id] = {
                    'x': 0.0, 'y': 0.0,
                    'vx': 0.0, 'vy': 0.0,
                    'entered': frame,
                    'exited': None
                }

    # Friction coefficient
    FRICTION = 0.01
    SPEED_THRESHOLD = 0.1

    outcomes = []
    exited_objects = set()

    # Process each sample frame
    prev_frame = int(start)

    for frame in sample_frames:
        if frame <= start:
            continue

        # Interpolate from previous frame to current frame
        dt = frame - prev_frame
        if dt <= 0:
            prev_frame = frame
            continue

        # First, check for collisions at this frame
        if frame in collision_events:
            for obj1, obj2 in collision_events[frame]:
                if obj1 in states and obj2 in states:
                    if states[obj1]['exited'] is None and states[obj2]['exited'] is None:
                        if frame >= states[obj1]['entered'] and frame >= states[obj2]['entered']:
                            # Handle elastic collision
                            _handle_collision(states[obj1], states[obj2])
                            outcomes.append({
                                "time": float(frame),
                                "kind": "collision",
                                "entities": [obj1, obj2],
                                "value": None,
                                "src": []
                            })

        # Update positions and apply friction for all objects
        for obj_id in list(states.keys()):
            state = states[obj_id]
            if state['exited'] is not None:
                continue
            if frame < state['entered']:
                continue

            # Apply friction and move
            for _ in range(int(dt)):
                _apply_friction(state, FRICTION, SPEED_THRESHOLD)
                state['x'] += state['vx']
                state['y'] += state['vy']

        # Check for exits
        if frame in exit_events:
            obj_id = exit_events[frame]
            if obj_id in states and states[obj_id]['exited'] is None:
                states[obj_id]['exited'] = float(frame)
                outcomes.append({
                    "time": float(frame),
                    "kind": "exit",
                    "entities": [obj_id],
                    "value": None,
                    "src": []
                })
                exited_objects.add(obj_id)

        # Record motion for active objects
        for obj_id in states:
            state = states[obj_id]
            if state['exited'] is not None:
                continue
            if frame < state['entered']:
                continue
            if frame in exited_objects:
                continue

            outcomes.append({
                "time": float(frame),
                "kind": "motion",
                "entities": [obj_id],
                "value": None,
                "src": []
            })

        prev_frame = frame

    return outcomes


def _get_collision_events(doc, scope):
    """Parse collision events from the Events node."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return {}

    children_nodes = children(doc, scope_node)
    events_node = None
    for child in children_nodes:
        if child['title'].endswith(': Events'):
            events_node = child
            break

    if not events_node:
        return {}

    collisions = {}
    lines = events_node['lines']
    for line in lines:
        match = re.match(r"Frame (\d+): (Object \d+) \(.*?\) collides with (Object \d+) \(.*?\)", line)
        if match:
            frame = int(match.group(1))
            obj1 = match.group(2)
            obj2 = match.group(3)
            if frame not in collisions:
                collisions[frame] = []
            collisions[frame].append((obj1, obj2))

    return collisions


def _get_exit_events(doc, scope):
    """Parse exit events from the Events node."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return {}

    children_nodes = children(doc, scope_node)
    events_node = None
    for child in children_nodes:
        if child['title'].endswith(': Events'):
            events_node = child
            break

    if not events_node:
        return {}

    exits = {}
    lines = events_node['lines']
    for line in lines:
        match = re.match(r"Frame (\d+): (Object \d+) \(.*?\) exits the scene", line)
        if match:
            frame = int(match.group(1))
            obj_id = match.group(2)
            exits[frame] = obj_id

    return exits


def _apply_friction(state, friction, threshold):
    """Apply friction to an object's velocity."""
    vx, vy = state['vx'], state['vy']
    speed = math.sqrt(vx*vx + vy*vy)

    if speed > threshold:
        new_speed = max(0, speed - friction)
        if new_speed < threshold:
            state['vx'] = 0.0
            state['vy'] = 0.0
        else:
            state['vx'] = vx * new_speed / speed
            state['vy'] = vy * new_speed / speed


def _handle_collision(state1, state2, restitution=1.0):
    """Handle elastic collision between two objects."""
    dx = state1['x'] - state2['x']
    dy = state1['y'] - state2['y']
    dist = math.sqrt(dx*dx + dy*dy)

    if dist < 0.001:
        nx, ny = 1.0, 0.0
    else:
        nx, ny = dx/dist, dy/dist

    v1x, v1y = state1['vx'], state1['vy']
    v2x, v2y = state2['vx'], state2['vy']

    rel_v = (v1x - v2x)*nx + (v1y - v2y)*ny

    if rel_v > 0:
        return

    # Equal mass elastic collision
    impulse = rel_v * (1 + restitution) / 2

    state1['vx'] -= impulse * nx
    state1['vy'] -= impulse * ny
    state2['vx'] += impulse * nx
    state2['vy'] += impulse * ny
